"""Portable Python product contract. Generated files are data, never executed here."""
import ast
import hashlib
import io
import json
from pathlib import PurePosixPath, Path
import re
import stat
import zipfile

BASE_IMAGE='python:3.12.13-slim@sha256:229a2c5bfa27522db7815ea81f9bed70af17ccb9de9fc7ad142b1877b5830d36'
MAX_PACKAGE=2_000_000
RESERVED={'product.json','Dockerfile','docker-compose.yml','.dockerignore','.env.example','runtime-requirements.lock','install.md','checks.json'}

def safe_path(name):
    if not isinstance(name,str) or len(name)>180 or not re.fullmatch(r'[a-zA-Z0-9_./-]+',name):
        raise ValueError('Invalid product path')
    path=PurePosixPath(name)
    if path.is_absolute() or any(p in {'','..','.'} or p.startswith('.') for p in name.split('/')):
        raise ValueError('Hidden files and traversal are forbidden')
    if path.suffix not in {'.py','.sql','.md','.json','.csv','.css','.html','.svg'}:
        raise ValueError('Unsupported source type')
    return name


def validate_sources(files):
    total=0
    for name,content in files.items():
        safe_path(name)
        if name in RESERVED or len(content)>90_000:raise ValueError('Reserved or oversized file')
        total+=len(content.encode())
        if name.endswith('.py'):
            ast.parse(content,filename=name) # syntax only; no import/compile/exec of model code
    if total>MAX_PACKAGE:raise ValueError('Sources exceed package limit')


def dockerfile():
    # Every RUN precedes COPY of untrusted sources. The model cannot add build commands.
    return f'''FROM {BASE_IMAGE}
ENV PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1 PIP_DISABLE_PIP_VERSION_CHECK=1
WORKDIR /product
COPY runtime-requirements.lock /runtime-requirements.lock
RUN pip install --no-cache-dir -r /runtime-requirements.lock
COPY --chown=10001:10001 . /product
USER 10001:10001
CMD ["python", "app.py"]
'''


def proxy_code(target):
    if not re.fullmatch(r'[a-z0-9-]+',target):raise ValueError('Invalid target')
    return """import asyncio
async def handle(reader,writer):
    try:
        upstream,out=await asyncio.wait_for(asyncio.open_connection('TARGET',8000),5)
        async def copy(source,destination):
            while chunk:=await asyncio.wait_for(source.read(65536),30):
                destination.write(chunk);await destination.drain()
            destination.close()
        await asyncio.gather(copy(reader,out),copy(upstream,writer))
    except Exception:
        writer.close()
async def main():
    server=await asyncio.start_server(handle,'0.0.0.0',8000)
    async with server:await server.serve_forever()
asyncio.run(main())
""".replace('TARGET',target)


def compose(product_key,version,kind):
    alias='app-'+product_key
    service={
        'build':'.','image':f'ai-product-{product_key}:{version}',
        'user':'10001:10001','read_only':True,'cap_drop':['ALL'],
        'security_opt':['no-new-privileges:true'],'pids_limit':64,'cpus':1,'mem_limit':'512m',
        'tmpfs':['/tmp:size=64m,mode=1777'],
        'volumes':['product-data:/data'],
        'environment':{'DATABASE_URL':'${PRODUCT_DATABASE_URL:-}','OUTPUT_DIR':'/data'},
        'networks':{'products':{'aliases':[alias]}},
        'logging':{'driver':'json-file','options':{'max-size':'5m','max-file':'2'}},
        'restart':'unless-stopped' if kind=='service' else 'no',
    }
    networks={'products':{'external':True,'name':'ai-products'}}
    services={'app':service}
    if kind=='service':
        service['healthcheck']={'test':['CMD','python','-c',"import urllib.request; urllib.request.urlopen('http://127.0.0.1:8000/health',timeout=2)"],
            'interval':'10s','timeout':'3s','retries':6}
        networks['access']={}
        services['gateway']={'image':BASE_IMAGE,'user':'10001:10001','read_only':True,
            'cap_drop':['ALL'],'security_opt':['no-new-privileges:true'],'pids_limit':32,'cpus':0.25,'mem_limit':'64m',
            'command':['python','-c',proxy_code(alias)],'networks':['products','access'],
            'ports':['127.0.0.1:${PRODUCT_PORT:-8600}:8000'],'restart':'unless-stopped',
            'depends_on':{'app':{'condition':'service_healthy'}},
            'healthcheck':{'test':['CMD','python','-c',"import urllib.request; urllib.request.urlopen('http://127.0.0.1:8000/health',timeout=2)"],
                'interval':'2s','timeout':'3s','retries':20},
            'logging':{'driver':'json-file','options':{'max-size':'5m','max-file':'2'}}}
    return {'name':'product-'+product_key,'services':services,
        'networks':networks,'volumes':{'product-data':{}}}


def requirements():
    # Dependency policy is owned by the platform, not generated by an LLM.
    return Path(__file__).with_name('product_templates').joinpath('runtime-requirements.lock').read_text()


def build_package(solution,product_key,version,story_id,revision,contributions=None):
    if not re.fullmatch(r'p-[0-9a-f]{12}',product_key) or not re.fullmatch(r'1\.0\.[1-9][0-9]*',version):
        raise ValueError('Invalid product identity')
    files={k:v.encode() for k,v in solution.files.items()}
    files['Dockerfile']=dockerfile().encode()
    files['runtime-requirements.lock']=requirements().encode()
    files['docker-compose.yml']=(json.dumps(compose(product_key,version,solution.kind),indent=2)+'\n').encode()
    files['.dockerignore']=b'.env\n.env.*\n!.env.example\n.git\n__pycache__\n*.pyc\n'
    files['.env.example']=b'PRODUCT_PORT=8600\nPRODUCT_DATABASE_URL=\n'
    files['architecture.md']=(solution.architecture+'\n\n'+json.dumps(contributions or {},ensure_ascii=False,indent=2)).encode()
    files['install.md']=installation(product_key,version,solution).encode()
    metadata={'contract_version':1,'product_key':product_key,'version':version,'story_id':str(story_id),'revision':revision,
        'title':solution.title,'kind':solution.kind,'output_type':solution.output_type,'needs_database':solution.needs_database,
        'runtime_profile':'python-locked-v1','health_path':'/health' if solution.kind=='service' else None,
        'result_path':'/result' if solution.kind=='service' else '/data/result.json',
        'files':{k:{'sha256':hashlib.sha256(v).hexdigest(),'size':len(v)} for k,v in sorted(files.items())}}
    files['product.json']=(json.dumps(metadata,ensure_ascii=False,indent=2)+'\n').encode()
    output=io.BytesIO()
    with zipfile.ZipFile(output,'w',zipfile.ZIP_DEFLATED) as archive:
        for name,content in sorted(files.items()):
            item=zipfile.ZipInfo(f'products/{product_key}/{name}',date_time=(2026,1,1,0,0,0))
            item.external_attr=(stat.S_IFREG|0o644)<<16
            archive.writestr(item,content,compress_type=zipfile.ZIP_DEFLATED)
    content=output.getvalue()
    if len(content)>MAX_PACKAGE:raise ValueError('Package too large')
    return content,metadata


def inspect_package(content):
    if len(content)>MAX_PACKAGE:raise ValueError('Package too large')
    files={};total=0
    with zipfile.ZipFile(io.BytesIO(content)) as archive:
        if len(archive.infolist())>50:raise ValueError('Too many package entries')
        for item in archive.infolist():
            parts=item.filename.split('/')
            if len(parts)<3 or parts[0]!='products' or not re.fullmatch(r'p-[a-f0-9]{12}',parts[1]):raise ValueError('Invalid package root')
            name='/'.join(parts[2:])
            if name not in RESERVED:safe_path(name)
            if item.filename in files or stat.S_ISLNK(item.external_attr>>16):raise ValueError('Duplicate or linked entry')
            if files and parts[1]!=next(iter(files)).split('/')[1]:raise ValueError('Multiple product roots')
            total+=item.file_size
            if total>MAX_PACKAGE or item.file_size>MAX_PACKAGE:raise ValueError('Expanded package too large')
            files[item.filename]=archive.read(item)
    root=next(iter(files)).split('/')[1] if files else ''
    prefix='products/'+root+'/'
    flat={k[len(prefix):]:v for k,v in files.items()}
    metadata=json.loads(flat['product.json'])
    if metadata['contract_version']!=1 or metadata['product_key']!=root:raise ValueError('Invalid manifest identity')
    if not re.fullmatch(r'1\.0\.[1-9][0-9]*',metadata['version']) or metadata['kind'] not in {'service','job'}:raise ValueError('Invalid release identity')
    expected=metadata['files']
    if set(flat)!=(set(expected)|{'product.json'}):raise ValueError('Manifest file set changed')
    for name,entry in expected.items():
        if len(flat[name])!=entry['size'] or hashlib.sha256(flat[name]).hexdigest()!=entry['sha256']:raise ValueError('Package digest mismatch')
    if flat['Dockerfile'].decode()!=dockerfile() or flat['runtime-requirements.lock'].decode()!=requirements():raise ValueError('Build policy changed')
    if json.loads(flat['docker-compose.yml'])!=compose(root,metadata['version'],metadata['kind']):raise ValueError('Compose policy changed')
    sources={k:v.decode() for k,v in flat.items() if k not in RESERVED}
    validate_sources(sources)
    if 'app.py' not in sources or not any(k.startswith('tests/test_') for k in sources):raise ValueError('Missing source/tests')
    return metadata,flat


def installation(key,version,solution):
    return f'''# {solution.title} — {version}

Пакет самостоятельный: API, worker, OpenProject и BookStack команды ему не нужны.
Python 3.12, Docker Engine/Desktop и Compose v2; 1 CPU / 512 MB на приложение,
место для образов и данных; первоначальная сборка требует HTTPS к Docker Hub и PyPI.

## Общая инфраструктура продуктов

Несколько продуктов используют одну среду. Один раз создайте внутреннюю сеть:
`docker network create --internal --label ai-team.product-managed=true ai-products`.
При необходимости используйте общую PostgreSQL, подключённую к этой сети;
для каждого продукта выделяйте отдельную базу и роль с правами только в своей базе.
Служебная PostgreSQL AI-команды для этого не используется.

## Установка

Из каталога products/{key}/: скопируйте `.env.example` в `.env` (не передавайте его в Git),
задайте свободный PRODUCT_PORT и, если нужна БД, PRODUCT_DATABASE_URL с отдельной ролью.
Сборка: `docker compose build`. Создайте volume командой `docker compose create`.
Перед первым стартом инициализируйте права volume (образ уже собран):
`docker compose run --rm --no-deps --user 0 --cap-add CHOWN --entrypoint /usr/bin/chown app 10001:10001 /data`.
Проверка: `docker compose run --rm --no-deps app python -m unittest discover -s tests -v`.
Запуск: `docker compose up -d`. Доверенный gateway публикует сервис только на 127.0.0.1:PRODUCT_PORT;
для переноса на другой хост измените .env и скопируйте весь каталог.
Для job используйте `docker compose run --rm app`; restart отключён.

## Результат и проверки

Сервис: GET /health (HTTP 200) и GET /result на http://127.0.0.1:PRODUCT_PORT.
Job: /data/result.json; файлы результата также сохраняются в /data.
Получение файлов: `docker compose cp app:/data ./results` (сервис должен существовать).
Формат результата: {solution.output_type}. Секреты, URL БД и данные не включаются в логи.
Проверяйте содержание результата по критериям user story, одного healthcheck недостаточно.

## Данные, обновление и восстановление

{solution.operating_notes}

Исходный код миграций/инициализации, если нужен продукту, находится в этом пакете.
Новая версия поставляется отдельным проверенным пакетом; перед обновлением сделайте backup
продуктовой БД (pg_dump) и volume /data, сохраните прежний пакет и приватный .env.
Применяйте миграции в порядке, описанном выше; при несовместимых миграциях откат выполняется
восстановлением БД и volume из копии и запуском прежнего образа.
Остановка: `docker compose stop`; удаление контейнеров: `docker compose down`.
Не используйте `down -v`, если данные должны сохраняться.
Сеть по умолчанию закрыта от Интернета. Загрузка внешних источников требует отдельно
описанной и настроенной оператором сетевой политики и расписания; скрытого доступа нет.
'''
